/**
 * FORECOURT WORKS LTD — Dispenser Breakdown Financial Loss Calculator
 * Demo tool for R&M service conversations
 */
(function () {
  'use strict';

  const EMBEDDED_LOGO_MARK_PNG = 'data:image/png;base64,';

  const state = {
    product: 'PMS',
    lastCalc: null
  };

  const $ = (s) => document.querySelector(s);
  const $$ = (s) => document.querySelectorAll(s);

  const PERIODS = [
    { key: 'minute', label: 'Per minute', hours: 1 / 60 },
    { key: 'hour', label: 'Per hour', hours: 1 },
    { key: 'day', label: 'Per day', hours: null }, // uses operating hours
    { key: 'week', label: 'Per week', hours: null },
    { key: 'month', label: 'Per month (30d)', hours: null },
    { key: 'quarter', label: 'Per quarter (90d)', hours: null },
    { key: 'semi', label: 'Semi-annual (182.5d)', hours: null },
    { key: 'year', label: 'Annual (365d)', hours: null }
  ];

  const SCENARIOS = [
    { label: '4 hours (quick fix delayed)', hours: 4 },
    { label: '1 operating day', days: 1 },
    { label: '3 days', days: 3 },
    { label: '1 week', days: 7 },
    { label: '2 weeks', days: 14 },
    { label: '1 month', days: 30 }
  ];

  function toast(msg, type) {
    const el = $('#toast');
    el.textContent = msg;
    el.className = 'toast show' + (type ? ' ' + type : '');
    setTimeout(() => { el.className = 'toast'; }, 3200);
  }

  function formatKES(n) {
    if (n == null || isNaN(n)) return '—';
    return 'KES ' + Number(n).toLocaleString('en-KE', { maximumFractionDigits: 0 });
  }

  function formatL(n) {
    if (n == null || isNaN(n)) return '—';
    return Number(n).toLocaleString('en-KE', { maximumFractionDigits: 1 }) + ' L';
  }

  function formatDateDDMonYYYY(iso) {
    if (!iso) return '—';
    const d = new Date(iso + 'T00:00:00');
    if (isNaN(d.getTime())) return iso;
    const m = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
    return String(d.getDate()).padStart(2,'0') + '-' + m[d.getMonth()] + '-' + d.getFullYear();
  }

  function todayISO() {
    const d = new Date();
    return d.toISOString().slice(0, 10);
  }

  /** Tabs: show/hide only — never rebuild inputs (preserves data) */
  function switchTab(id) {
    $$('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === id));
    $$('.tab-panel').forEach(p => p.classList.toggle('active', p.id === 'tab-' + id));
  }

  function readInputs() {
    const mode = $('#throughput-mode').value;
    const volume = parseFloat($('#volume').value) || 0;
    const hoursDay = parseFloat($('#hours-day').value) || 18;
    const daysWeek = parseFloat($('#days-week').value) || 7;
    const util = (parseFloat($('#utilisation').value) || 100) / 100;
    const price = parseFloat($('#price-kes').value) || 0;
    const margin = parseFloat($('#margin-kes').value);
    const nozzles = parseFloat($('#nozzles').value) || 1;

    let litersPerOperatingHour = 0;
    if (mode === 'hourly') {
      litersPerOperatingHour = volume * util * nozzles;
    } else if (mode === 'monthly') {
      const daysMonth = (daysWeek / 7) * 30;
      const daily = daysMonth > 0 ? volume / daysMonth : 0;
      litersPerOperatingHour = hoursDay > 0 ? (daily / hoursDay) * util * nozzles : 0;
    } else {
      // daily
      litersPerOperatingHour = hoursDay > 0 ? (volume / hoursDay) * util * nozzles : 0;
    }

    return {
      client: ($('#client-name').value || '').trim(),
      site: ($('#site-location').value || '').trim(),
      preparedBy: ($('#prepared-by').value || '').trim(),
      date: $('#calc-date').value || todayISO(),
      product: state.product,
      mode,
      volume,
      hoursDay,
      daysWeek,
      util,
      price,
      margin: isNaN(margin) ? null : margin,
      nozzles,
      litersPerOperatingHour,
      downtimeValue: parseFloat($('#downtime-value').value) || 0,
      downtimeUnit: $('#downtime-unit').value,
      repairCost: parseFloat($('#repair-cost').value) || 0
    };
  }

  function hoursForPeriod(key, inp) {
    const h = inp.hoursDay;
    const dw = inp.daysWeek;
    switch (key) {
      case 'minute': return 1 / 60;
      case 'hour': return 1;
      case 'day': return h;
      case 'week': return h * dw;
      case 'month': return h * (dw / 7) * 30;
      case 'quarter': return h * (dw / 7) * 90;
      case 'semi': return h * (dw / 7) * 182.5;
      case 'year': return h * (dw / 7) * 365;
      default: return 0;
    }
  }

  function lossForHours(hours, inp) {
    const liters = inp.litersPerOperatingHour * hours;
    const revenue = liters * inp.price;
    const margin = inp.margin != null ? liters * inp.margin : null;
    return { liters, revenue, margin };
  }

  function calculate() {
    const inp = readInputs();
    if (!inp.price || inp.price <= 0) {
      toast('Enter selling price (KES/L)', 'error');
      switchTab('inputs');
      return null;
    }
    if (!inp.volume || inp.volume <= 0) {
      toast('Enter average volume', 'error');
      switchTab('inputs');
      return null;
    }
    if (inp.litersPerOperatingHour <= 0) {
      toast('Check volume and operating hours', 'error');
      return null;
    }

    const rows = PERIODS.map(p => {
      const hrs = hoursForPeriod(p.key, inp);
      const loss = lossForHours(hrs, inp);
      return { ...p, hours: hrs, ...loss };
    });

    // Custom downtime total
    let dtHours = inp.downtimeValue;
    if (inp.downtimeUnit === 'days') dtHours = inp.downtimeValue * inp.hoursDay;
    if (inp.downtimeUnit === 'weeks') dtHours = inp.downtimeValue * inp.hoursDay * inp.daysWeek;
    const downtimeLoss = lossForHours(dtHours, inp);

    const scenarios = SCENARIOS.map(s => {
      let hrs;
      if (s.hours != null) hrs = s.hours;
      else hrs = s.days * inp.hoursDay * (s.days >= 7 ? (inp.daysWeek / 7) : 1);
      // for multi-day use calendar days * daily operating hours * (if long, scale by open days ratio)
      if (s.days != null) {
        if (s.days === 1) hrs = inp.hoursDay;
        else if (s.days < 7) hrs = s.days * inp.hoursDay;
        else hrs = s.days * inp.hoursDay * (inp.daysWeek / 7);
      }
      const loss = lossForHours(hrs, inp);
      return { label: s.label, ...loss, vsRepair: inp.repairCost > 0 ? loss.revenue / inp.repairCost : null };
    });

    state.lastCalc = { inp, rows, downtimeLoss, dtHours, scenarios };
    renderResults();
    renderScenarios();
    renderPitch();
    switchTab('results');
    toast('Loss calculation updated', 'success');
    return state.lastCalc;
  }

  function renderResults() {
    const c = state.lastCalc;
    if (!c) return;
    const { inp, rows, downtimeLoss } = c;
    $('#result-product').textContent = inp.product;
    $('#result-summary').textContent =
      (inp.client ? inp.client + ' · ' : '') +
      (inp.site ? inp.site + ' · ' : '') +
      'Effective throughput ' + formatL(inp.litersPerOperatingHour) + '/operating hour · ' +
      formatKES(inp.price) + '/L · ' + formatDateDDMonYYYY(inp.date);

    const dayRow = rows.find(r => r.key === 'day');
    const monthRow = rows.find(r => r.key === 'month');
    $('#impact-main').textContent = formatKES(dayRow.revenue) + ' / day';
    $('#impact-sub').textContent = formatL(dayRow.liters) + ' per day · ' + formatKES(monthRow.revenue) + ' per month at risk';

    $('#kpi-min').textContent = formatKES(rows.find(r => r.key === 'minute').revenue);
    $('#kpi-hour').textContent = formatKES(rows.find(r => r.key === 'hour').revenue);
    $('#kpi-day').textContent = formatKES(dayRow.revenue);
    $('#kpi-month').textContent = formatKES(monthRow.revenue);

    const tb = $('#loss-tbody');
    tb.innerHTML = rows.map(r => `
      <tr>
        <td>${r.label}</td>
        <td class="liters">${formatL(r.liters)}</td>
        <td class="kes">${formatKES(r.revenue)}</td>
        <td>${r.margin != null ? formatKES(r.margin) : '—'}</td>
      </tr>
    `).join('');

    const note = $('#compare-note');
    if (inp.repairCost > 0 && downtimeLoss.revenue > 0) {
      note.style.display = 'block';
      const ratio = downtimeLoss.revenue / inp.repairCost;
      note.innerHTML = `<b>Your estimated downtime</b> (${inp.downtimeValue} ${inp.downtimeUnit}):
        <b>${formatL(downtimeLoss.liters)}</b> · <b>${formatKES(downtimeLoss.revenue)}</b> revenue at risk.
        That is <b>${ratio.toFixed(1)}×</b> the estimated repair/response cost of ${formatKES(inp.repairCost)}.
        Fast R&amp;M response pays for itself by protecting pump sales.`;
    } else {
      note.style.display = 'none';
    }
  }

  function renderScenarios() {
    const c = state.lastCalc;
    if (!c) return;
    $('#scenario-tbody').innerHTML = c.scenarios.map(s => `
      <tr>
        <td>${s.label}</td>
        <td class="liters">${formatL(s.liters)}</td>
        <td class="kes">${formatKES(s.revenue)}</td>
        <td>${s.vsRepair != null ? s.vsRepair.toFixed(1) + '× repair cost' : '—'}</td>
      </tr>
    `).join('');
  }

  function renderPitch() {
    const c = state.lastCalc;
    if (!c) return;
    const { inp, rows, downtimeLoss } = c;
    const day = rows.find(r => r.key === 'day');
    const week = rows.find(r => r.key === 'week');
    const month = rows.find(r => r.key === 'month');
    const year = rows.find(r => r.key === 'year');

    $('#pitch-body').innerHTML = `
      <p style="margin-bottom:10px;"><b>Client:</b> ${inp.client || '—'} &nbsp;|&nbsp; <b>Site:</b> ${inp.site || '—'} &nbsp;|&nbsp; <b>Product:</b> ${inp.product}</p>
      <p style="margin-bottom:10px;">At current throughput and pump price, every <b>hour</b> this ${inp.product} stream is offline costs about
        <b style="color:#b91c1c;">${formatKES(rows.find(r => r.key === 'hour').revenue)}</b>
        (${formatL(rows.find(r => r.key === 'hour').liters)}).</p>
      <p style="margin-bottom:10px;">That scales to approximately:</p>
      <ul style="margin:0 0 12px 18px;">
        <li><b>${formatKES(day.revenue)}</b> per day (${formatL(day.liters)})</li>
        <li><b>${formatKES(week.revenue)}</b> per week</li>
        <li><b>${formatKES(month.revenue)}</b> per month</li>
        <li><b>${formatKES(year.revenue)}</b> per year if chronic reliability issues persist</li>
      </ul>
      <p style="margin-bottom:10px;">For the downtime scenario entered (<b>${inp.downtimeValue} ${inp.downtimeUnit}</b>),
        estimated sales exposure is <b style="color:#b91c1c;">${formatKES(downtimeLoss.revenue)}</b>
        (${formatL(downtimeLoss.liters)})${inp.margin != null ? ', with gross margin exposure of <b>' + formatKES(downtimeLoss.margin) + '</b>' : ''}.</p>
      <p style="margin-bottom:10px;"><b>Conversation close:</b> A structured Reliability &amp; Maintenance plan from Forecourt Works — preventive inspections,
        rapid response, and metrology-ready equipment health — is designed to prevent these losses, not merely react after the pump is already silent.</p>
      <p style="color:#64748b;font-size:0.85rem;">Figures are illustrative based on data entered for this demonstration. Actual results depend on site traffic, pricing, and operating patterns.</p>
    `;
  }

  async function generatePDF() {
    if (!state.lastCalc) {
      toast('Calculate losses first', 'error');
      switchTab('inputs');
      return;
    }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const pageW = 210, pageH = 297;
    const outer = 7, margin = 14;
    const usable = pageW - margin * 2;
    const navy = [13, 71, 140];
    const dark = [30, 38, 50];
    const red = [185, 28, 28];
    const grey = [100, 110, 120];
    let y = margin;

    function drawFrame() {
      doc.setDrawColor(...navy);
      doc.setLineWidth(0.6);
      doc.rect(outer, outer, pageW - outer * 2, pageH - outer * 2);
      doc.setLineWidth(0.25);
      doc.rect(outer + 1.5, outer + 1.5, pageW - (outer + 1.5) * 2, pageH - (outer + 1.5) * 2);
      // logo
      try {
        doc.addImage(EMBEDDED_LOGO_MARK_PNG, 'PNG', pageW - outer - 44, outer + 2, 40, 7);
      } catch (_) {}
    }

    function footer(pageNo, total) {
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);
      doc.setTextColor(...grey);
      doc.text('FORECOURT WORKS LIMITED · Ramco Court, GT 3B, South C, Nairobi · +254 729-002-087', margin, pageH - 8);
      doc.text('Page ' + pageNo + ' of ' + total, pageW - margin, pageH - 8, { align: 'right' });
      doc.text('Doc: FSW-DEMO-LOSS-01 · Engineering Reliability Into Every Forecourt', margin, pageH - 4.5);
    }

    function checkPage(need) {
      if (y + need > pageH - 16) {
        doc.addPage();
        drawFrame();
        y = margin + 6;
      }
    }

    drawFrame();

    // Header company block
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...navy);
    doc.text('FORECOURT WORKS LIMITED', margin, y + 4);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...dark);
    doc.text('Ramco Court, GT 3B, South C, Nairobi', margin, y + 8);
    doc.text('Phone: +(254) 729-002-087  |  sales@forecourtworks.co.ke  |  www.forecourtworks.co.ke', margin, y + 12);
    doc.setFont('helvetica', 'italic');
    doc.setTextColor(196, 92, 10);
    doc.text('Engineering Reliability Into Every Forecourt', margin, y + 16);
    y += 22;

    doc.setDrawColor(...navy);
    doc.setLineWidth(0.4);
    doc.line(margin, y, pageW - margin, y);
    y += 6;

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(13);
    doc.setTextColor(...navy);
    doc.text('DISPENSER BREAKDOWN — FINANCIAL LOSS ILLUSTRATION', pageW / 2, y, { align: 'center' });
    y += 7;
    doc.setFontSize(9);
    doc.setTextColor(...dark);
    doc.text('Demonstration tool for Reliability & Maintenance service conversations', pageW / 2, y, { align: 'center' });
    y += 8;

    const { inp, rows, downtimeLoss, scenarios } = state.lastCalc;

    // Client box
    doc.setFillColor(224, 235, 245);
    doc.setDrawColor(...navy);
    doc.rect(margin, y, usable, 18, 'FD');
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...dark);
    doc.text('Client: ' + (inp.client || '—'), margin + 3, y + 5);
    doc.text('Site: ' + (inp.site || '—'), margin + usable * 0.45, y + 5);
    doc.text('Date: ' + formatDateDDMonYYYY(inp.date), margin + 3, y + 10);
    doc.text('Prepared by: ' + (inp.preparedBy || '—'), margin + usable * 0.45, y + 10);
    doc.text('Product: ' + inp.product + '   |   Price: ' + formatKES(inp.price) + '/L   |   Effective rate: ' + formatL(inp.litersPerOperatingHour) + '/op. hour', margin + 3, y + 15);
    y += 24;

    // Impact
    doc.setFillColor(127, 29, 29);
    doc.rect(margin, y, usable, 14, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(255, 255, 255);
    const day = rows.find(r => r.key === 'day');
    doc.text('AT RISK: ' + formatKES(day.revenue) + ' REVENUE PER OPERATING DAY', pageW / 2, y + 6, { align: 'center' });
    doc.setFontSize(8);
    doc.text(formatL(day.liters) + '  ·  ' + formatKES(rows.find(r => r.key === 'month').revenue) + ' / month  ·  ' + formatKES(rows.find(r => r.key === 'year').revenue) + ' / year', pageW / 2, y + 11, { align: 'center' });
    y += 20;

    // Table
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(...navy);
    doc.text('1. LOSS BY PERIOD (Litres & KES)', margin, y);
    y += 4;

    const colW = [usable * 0.28, usable * 0.24, usable * 0.24, usable * 0.24];
    const headers = ['Period', 'Sales loss (L)', 'Revenue (KES)', 'Margin (KES)'];
    doc.setFillColor(...navy);
    doc.rect(margin, y, usable, 7, 'F');
    doc.setFontSize(7.5);
    doc.setTextColor(255, 255, 255);
    let x = margin;
    headers.forEach((h, i) => {
      doc.text(h, x + 1.5, y + 4.8);
      x += colW[i];
    });
    y += 7;

    doc.setFont('helvetica', 'normal');
    rows.forEach((r, idx) => {
      checkPage(8);
      if (idx % 2 === 0) {
        doc.setFillColor(248, 250, 252);
        doc.rect(margin, y, usable, 7, 'F');
      }
      doc.setDrawColor(200, 210, 220);
      doc.setLineWidth(0.1);
      doc.rect(margin, y, usable, 7);
      doc.setTextColor(...dark);
      doc.setFontSize(7.5);
      x = margin;
      const vals = [
        r.label,
        formatL(r.liters),
        formatKES(r.revenue),
        r.margin != null ? formatKES(r.margin) : '—'
      ];
      vals.forEach((v, i) => {
        if (i === 2) doc.setTextColor(...red);
        else doc.setTextColor(...dark);
        doc.setFont('helvetica', i === 0 ? 'bold' : 'normal');
        doc.text(String(v), x + 1.5, y + 4.8);
        x += colW[i];
      });
      y += 7;
    });
    y += 6;

    // Scenarios
    checkPage(40);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(...navy);
    doc.text('2. DOWNTIME SCENARIOS', margin, y);
    y += 4;
    doc.setFillColor(...navy);
    doc.rect(margin, y, usable, 7, 'F');
    doc.setFontSize(7.5);
    doc.setTextColor(255, 255, 255);
    const sCol = [usable * 0.34, usable * 0.22, usable * 0.24, usable * 0.20];
    ['Scenario', 'Litres lost', 'Revenue (KES)', 'vs Repair'].forEach((h, i) => {
      doc.text(h, margin + sCol.slice(0, i).reduce((a, b) => a + b, 0) + 1.5, y + 4.8);
    });
    y += 7;
    doc.setFont('helvetica', 'normal');
    scenarios.forEach((s, idx) => {
      checkPage(8);
      if (idx % 2 === 0) {
        doc.setFillColor(248, 250, 252);
        doc.rect(margin, y, usable, 7, 'F');
      }
      doc.setDrawColor(200, 210, 220);
      doc.rect(margin, y, usable, 7);
      const vals = [s.label, formatL(s.liters), formatKES(s.revenue), s.vsRepair != null ? s.vsRepair.toFixed(1) + 'x' : '—'];
      vals.forEach((v, i) => {
        doc.setTextColor(i === 2 ? red[0] : dark[0], i === 2 ? red[1] : dark[1], i === 2 ? red[2] : dark[2]);
        doc.text(String(v), margin + sCol.slice(0, i).reduce((a, b) => a + b, 0) + 1.5, y + 4.8);
      });
      y += 7;
    });
    y += 6;

    // Narrative
    checkPage(45);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(...navy);
    doc.text('3. WHY PROACTIVE R&M MATTERS', margin, y);
    y += 5;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(...dark);
    const narrative = 'Based on the figures supplied for this demonstration, prolonged dispenser downtime converts directly into lost pump sales and weakened customer confidence. '
      + 'A Reliability & Maintenance partnership with Forecourt Works Limited is structured to minimise unplanned outages through preventive inspection, rapid response, and metrology-aware equipment care. '
      + 'The cost of structured R&M is typically a fraction of even a few days of lost product throughput on a busy island.';
    const lines = doc.splitTextToSize(narrative, usable);
    doc.text(lines, margin, y);
    y += lines.length * 4 + 4;

    if (inp.repairCost > 0) {
      const msg = 'Estimated downtime exposure (' + inp.downtimeValue + ' ' + inp.downtimeUnit + '): ' + formatKES(downtimeLoss.revenue)
        + ' vs repair/response cost ' + formatKES(inp.repairCost) + ' (' + (downtimeLoss.revenue / inp.repairCost).toFixed(1) + 'x).';
      const ml = doc.splitTextToSize(msg, usable);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...red);
      doc.text(ml, margin, y);
      y += ml.length * 4 + 4;
    }

    y += 4;
    checkPage(25);
    doc.setFont('helvetica', 'italic');
    doc.setFontSize(7.5);
    doc.setTextColor(...grey);
    doc.text(doc.splitTextToSize('Disclaimer: Illustrative demonstration based on user-entered throughput and pricing. Not a financial audit, tax computation, or guarantee of actual site performance.', usable), margin, y);
    y += 12;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...dark);
    doc.text('Client acknowledgement: ________________________________  Date: _______________', margin, y);
    y += 8;
    doc.text('FSW representative: ________________________________  Date: _______________', margin, y);

    const total = doc.internal.getNumberOfPages();
    for (let i = 1; i <= total; i++) {
      doc.setPage(i);
      if (i > 1) drawFrame();
      footer(i, total);
    }
    // redraw frame on page 1 was already done; footers all pages
    // ensure frame on all pages
    for (let i = 1; i <= total; i++) {
      doc.setPage(i);
      drawFrame();
      footer(i, total);
    }

    const safeClient = (inp.client || 'Client').replace(/[\\/:*?"<>|]/g, '-').slice(0, 40);
    const fileName = 'FSW Loss Illustration - ' + inp.product + ' - ' + safeClient + '.pdf';
    doc.save(fileName);
    toast('PDF ready: ' + fileName, 'success');
  }

  function bindProducts() {
    $$('.product-chip').forEach(chip => {
      chip.addEventListener('click', () => {
        $$('.product-chip').forEach(c => c.classList.remove('selected'));
        chip.classList.add('selected');
        state.product = chip.dataset.product;
        $('#product').value = state.product;
      });
    });
  }

  function bindThroughputMode() {
    $('#throughput-mode').addEventListener('change', () => {
      const m = $('#throughput-mode').value;
      const label = $('#volume-label');
      if (m === 'hourly') label.textContent = 'Average litres per operating hour';
      else if (m === 'monthly') label.textContent = 'Average litres per month';
      else label.textContent = 'Average daily volume (Litres)';
    });
  }

  function init() {
    $('#calc-date').value = todayISO();
    $('#date-hint').textContent = 'Selected: ' + formatDateDDMonYYYY(todayISO());
    $('#calc-date').addEventListener('change', () => {
      $('#date-hint').textContent = 'Selected: ' + formatDateDDMonYYYY($('#calc-date').value);
    });

    bindProducts();
    bindThroughputMode();

    $$('.tab-btn').forEach(btn => {
      btn.addEventListener('click', () => switchTab(btn.dataset.tab));
    });

    $('#btn-calculate').addEventListener('click', calculate);
    $('#btn-reset').addEventListener('click', () => {
      $('#volume').value = '';
      $('#price-kes').value = '';
      $('#margin-kes').value = '';
      $('#nozzles').value = '1';
      $('#hours-day').value = '18';
      $('#days-week').value = '7';
      $('#utilisation').value = '100';
      $('#downtime-value').value = '3';
      $('#downtime-unit').value = 'days';
      $('#repair-cost').value = '';
      toast('Inputs cleared');
    });
    $('#btn-pdf').addEventListener('click', generatePDF);
    $('#btn-pdf-2').addEventListener('click', generatePDF);
    $('#btn-to-pitch').addEventListener('click', () => switchTab('pitch'));

    // Auto-caps for text
    document.addEventListener('input', (e) => {
      if (e.target.classList.contains('auto-caps') && e.target.type === 'text') {
        const start = e.target.selectionStart;
        e.target.value = e.target.value.toUpperCase();
        try { e.target.setSelectionRange(start, start); } catch (_) {}
      }
    });
  }

  document.addEventListener('DOMContentLoaded', init);
})();
